static PyObject *
_vec_string_no_args_fastmethod(PyArrayObject* char_array,
                               PyArray_Descr* type, PyObject* method,
                               VecStrMethod meth_type, int is_unicode)
{
    PyArrayIterObject* in_iter = NULL;
    PyArrayObject* result = NULL;
    PyArrayIterObject* out_iter = NULL;

    in_iter = (PyArrayIterObject*)PyArray_IterNew((PyObject*)char_array);
    if (in_iter == NULL) {
        Py_DECREF(type);
        goto err;
    }

    result = (PyArrayObject*)PyArray_SimpleNewFromDescr(
            PyArray_NDIM(char_array), PyArray_DIMS(char_array), type);
    if (result == NULL) {
        goto err;
    }

    out_iter = (PyArrayIterObject*)PyArray_IterNew((PyObject*)result);
    if (out_iter == NULL) {
        goto err;
    }

    npy_intp itemsize = PyArray_ITEMSIZE(char_array);
    npy_intp num_chars = itemsize / sizeof(npy_ucs4);

    while (PyArray_ITER_NOTDONE(in_iter)) {
        int fast_result;

        if (is_unicode) {
            const npy_ucs4 *buf = (const npy_ucs4 *)in_iter->dataptr;
            switch (meth_type) {
                case VEC_STR_METH_ISALPHA:
                    fast_result = _unicode_isalpha_ascii(buf, num_chars);
                    break;
                case VEC_STR_METH_ISDIGIT:
                    fast_result = _unicode_isdigit_ascii(buf, num_chars);
                    break;
                /* ... etc ... */
                default:
                    fast_result = -1;
                    break;
            }
        } else {
            const char *buf = (const char *)in_iter->dataptr;
            switch (meth_type) {
                case VEC_STR_METH_ISALPHA:
                    fast_result = _bytes_isalpha_ascii(buf, itemsize);
                    break;
                /* ... etc ... */
                default:
                    fast_result = -1;
                    break;
            }
        }

        if (fast_result >= 0) {
            /* Fast path succeeded, set result directly */
            npy_bool val = (npy_bool)fast_result;
            if (PyArray_SETITEM(result, PyArray_ITER_DATA(out_iter), (PyObject*)&val)) {
                PyErr_SetString(PyExc_TypeError,
                    "result array type does not match underlying function");
                goto err;
            }
        } else {
            /* Fall back to Python method call */
            PyObject *item_result;
            PyObject *item = PyArray_ToScalar(in_iter->dataptr, in_iter->ao);
            if (item == NULL) {
                goto err;
            }
            item_result = PyObject_CallFunctionObjArgs(method, item, NULL);
            Py_DECREF(item);
            if (item_result == NULL) {
                goto err;
            }
            if (PyArray_SETITEM(result, PyArray_ITER_DATA(out_iter), item_result)) {
                Py_DECREF(item_result);
                PyErr_SetString(PyExc_TypeError,
                    "result array type does not match underlying function");
                goto err;
            }
            Py_DECREF(item_result);
        }

        PyArray_ITER_NEXT(in_iter);
        PyArray_ITER_NEXT(out_iter);
    }

    Py_DECREF(in_iter);
    Py_DECREF(out_iter);
    return (PyObject*)result;

err:
    Py_XDECREF(in_iter);
    Py_XDECREF(out_iter);
    Py_XDECREF(result);
    return 0;
}
