/*
 * Fast ASCII-path check functions for common string methods.
 * Each returns: 1 = True, 0 = False, -1 = need Python fallback (non-ASCII chars)
 * These operate directly on the raw array buffer, avoiding Python object
 * creation and method call overhead.
 */

typedef int (*_fast_unicode_check)(const npy_ucs4 *buf, npy_intp num_chars);
typedef int (*_fast_bytes_check)(const char *buf, npy_intp itemsize);

/* --- Unicode fast checks --- */

static int
_unicode_isalpha_ascii(const npy_ucs4 *buf, npy_intp num_chars)
{
    npy_ucs4 c = buf[0];
    if (c == 0) return 0;
    for (npy_intp i = 0; i < num_chars; i++) {
        c = buf[i];
        if (c == 0) return 1;
        if (c >= 128) return -1;
        if (!((c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z'))) return 0;
    }
    return 1;
}

static int
_unicode_isdigit_ascii(const npy_ucs4 *buf, npy_intp num_chars)
{
    npy_ucs4 c = buf[0];
    if (c == 0) return 0;
    for (npy_intp i = 0; i < num_chars; i++) {
        c = buf[i];
        if (c == 0) return 1;
        if (c >= 128) return -1;
        if (!(c >= '0' && c <= '9')) return 0;
    }
    return 1;
}

static int
_unicode_isalnum_ascii(const npy_ucs4 *buf, npy_intp num_chars)
{
    npy_ucs4 c = buf[0];
    if (c == 0) return 0;
    for (npy_intp i = 0; i < num_chars; i++) {
        c = buf[i];
        if (c == 0) return 1;
        if (c >= 128) return -1;
        if (!((c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z') ||
              (c >= '0' && c <= '9'))) return 0;
    }
    return 1;
}

static int
_unicode_isspace_ascii(const npy_ucs4 *buf, npy_intp num_chars)
{
    npy_ucs4 c = buf[0];
    if (c == 0) return 0;
    for (npy_intp i = 0; i < num_chars; i++) {
        c = buf[i];
        if (c == 0) return 1;
        if (c >= 128) return -1;
        if (!(c == ' ' || c == '\t' || c == '\n' || c == '\r' ||
              c == '\f' || c == '\v')) return 0;
    }
    return 1;
}

static int
_unicode_islower_ascii(const npy_ucs4 *buf, npy_intp num_chars)
{
    npy_ucs4 c = buf[0];
    if (c == 0) return 0;
    int has_cased = 0;
    for (npy_intp i = 0; i < num_chars; i++) {
        c = buf[i];
        if (c == 0) break;
        if (c >= 128) return -1;
        if (c >= 'A' && c <= 'Z') return 0;
        if (c >= 'a' && c <= 'z') has_cased = 1;
    }
    return has_cased ? 1 : 0;
}

static int
_unicode_isupper_ascii(const npy_ucs4 *buf, npy_intp num_chars)
{
    npy_ucs4 c = buf[0];
    if (c == 0) return 0;
    int has_cased = 0;
    for (npy_intp i = 0; i < num_chars; i++) {
        c = buf[i];
        if (c == 0) break;
        if (c >= 128) return -1;
        if (c >= 'a' && c <= 'z') return 0;
        if (c >= 'A' && c <= 'Z') has_cased = 1;
    }
    return has_cased ? 1 : 0;
}

static int
_unicode_istitle_ascii(const npy_ucs4 *buf, npy_intp num_chars)
{
    npy_ucs4 c = buf[0];
    if (c == 0) return 0;
    int has_cased = 0;
    int expect_upper = 1;
    for (npy_intp i = 0; i < num_chars; i++) {
        c = buf[i];
        if (c == 0) break;
        if (c >= 128) return -1;
        if (c >= 'A' && c <= 'Z') {
            if (!expect_upper) return 0;
            has_cased = 1;
            expect_upper = 0;
        }
        else if (c >= 'a' && c <= 'z') {
            if (expect_upper) return 0;
            has_cased = 1;
        }
        else {
            expect_upper = 1;
        }
    }
    return has_cased ? 1 : 0;
}

static int
_unicode_isnumeric_ascii(const npy_ucs4 *buf, npy_intp num_chars)
{
    npy_ucs4 c = buf[0];
    if (c == 0) return 0;
    for (npy_intp i = 0; i < num_chars; i++) {
        c = buf[i];
        if (c == 0) return 1;
        if (c >= 128) return -1;
        if (!(c >= '0' && c <= '9')) return 0;
    }
    return 1;
}

static int
_unicode_isdecimal_ascii(const npy_ucs4 *buf, npy_intp num_chars)
{
    npy_ucs4 c = buf[0];
    if (c == 0) return 0;
    for (npy_intp i = 0; i < num_chars; i++) {
        c = buf[i];
        if (c == 0) return 1;
        if (c >= 128) return -1;
        if (!(c >= '0' && c <= '9')) return 0;
