    for (npy_intp i = 0; i < num_chars; i++) {
        c = buf[i];
        if (c == 0) return 1;
        if (c >= 128) return -1;
        if (!((c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z') ||
              (c >= '0' && c <= '9'))) return 0;
    }
    return 1;
}

static int
_unicode_isspace_ascii(const npy_ucs4 *buf, npy_intp num_chars)
{
    npy_ucs4 c = buf[0];
    if (c == 0) return 0;
    for (npy_intp i = 0; i < num_chars; i++) {
        c = buf[i];
        if (c == 0) return 1;
        if (c >= 128) return -1;
        if (!(c == ' ' || c == '\t' || c == '\n' || c == '\r' ||
              c == '\f' || c == '\v')) return 0;
    }
    return 1;
}

static int
_unicode_islower_ascii(const npy_ucs4 *buf, npy_intp num_chars)
{
    npy_ucs4 c = buf[0];
    if (c == 0) return 0;
    int has_cased = 0;
    for (npy_intp i = 0; i < num_chars; i++) {
        c = buf[i];
        if (c == 0) break;
        if (c >= 128) return -1;
        if (c >= 'A' && c <= 'Z') return 0;
        if (c >= 'a' && c <= 'z') has_cased = 1;
    }
    return has_cased ? 1 : 0;
}

static int
_unicode_isupper_ascii(const npy_ucs4 *buf, npy_intp num_chars)
{
