}

static int
_unicode_istitle_ascii(const npy_ucs4 *buf, npy_intp num_chars)
{
    npy_ucs4 c = buf[0];
    if (c == 0) return 0;
    int has_cased = 0;
    int expect_upper = 1;
    for (npy_intp i = 0; i < num_chars; i++) {
        c = buf[i];
        if (c == 0) break;
        if (c >= 128) return -1;
        if (c >= 'A' && c <= 'Z') {
            if (!expect_upper) return 0;
            has_cased = 1;
            expect_upper = 0;
        }
        else if (c >= 'a' && c <= 'z') {
            if (expect_upper) return 0;
            has_cased = 1;
        }
        else {
            expect_upper = 1;
        }
    }
    return has_cased ? 1 : 0;
}

