/*
 * Fast-path loop: iterates elements using a direct C check function,
 * falling back to Python method call only for non-ASCII strings.
 */
static PyObject *
_vec_string_no_args_fast(PyArrayObject* char_array,
                         PyArray_Descr* type, PyObject* method,
                         _fast_unicode_check unicode_check,
                         _fast_bytes_check bytes_check,
                         int is_unicode)
{
    PyArrayIterObject* in_iter = NULL;
    PyArrayObject* result = NULL;
    PyArrayIterObject* out_iter = NULL;
    npy_intp itemsize;

    in_iter = (PyArrayIterObject*)PyArray_IterNew((PyObject*)char_array);
    if (in_iter == NULL) {
        Py_DECREF(type);
        goto err;
    }

    result = (PyArrayObject*)PyArray_SimpleNewFromDescr(
            PyArray_NDIM(char_array), PyArray_DIMS(char_array), type);
    if (result == NULL) {
        goto err;
    }

    out_iter = (PyArrayIterObject*)PyArray_IterNew((PyObject*)result);
    if (out_iter == NULL) {
        goto err;
    }

    itemsize = PyArray_ITEMSIZE(char_array);

    if (is_unicode) {
        npy_intp num_chars = itemsize / sizeof(npy_ucs4);
        while (PyArray_ITER_NOTDONE(in_iter)) {
            int fast_result = unicode_check(
                (const npy_ucs4 *)in_iter->dataptr, num_chars);
            if (fast_result >= 0) {
                *(npy_bool *)PyArray_ITER_DATA(out_iter) = (npy_bool)fast_result;
            }
            else {
                /* Fall back to Python method for non-ASCII strings */
                PyObject *item = PyArray_ToScalar(in_iter->dataptr, in_iter->ao);
                if (item == NULL) goto err;
                PyObject *item_result = PyObject_CallFunctionObjArgs(method, item, NULL);
                Py_DECREF(item);
                if (item_result == NULL) goto err;
                if (PyArray_SETITEM(result, PyArray_ITER_DATA(out_iter), item_result)) {
                    Py_DECREF(item_result);
                    PyErr_SetString(PyExc_TypeError,
                        "result array type does not match underlying function");
                    goto err;
                }
                Py_DECREF(item_result);
            }
            PyArray_ITER_NEXT(in_iter);
            PyArray_ITER_NEXT(out_iter);
        }
    }
    else {
        while (PyArray_ITER_NOTDONE(in_iter)) {
            int fast_result = bytes_check(
                (const char *)in_iter->dataptr, itemsize);
            if (fast_result >= 0) {
                *(npy_bool *)PyArray_ITER_DATA(out_iter) = (npy_bool)fast_result;
            }
            else {
                PyObject *item = PyArray_ToScalar(in_iter->dataptr, in_iter->ao);
                if (item == NULL) goto err;
                PyObject *item_result = PyObject_CallFunctionObjArgs(method, item, NULL);
                Py_DECREF(item);
                if (item_result == NULL) goto err;
                if (PyArray_SETITEM(result, PyArray_ITER_DATA(out_iter), item_result)) {
                    Py_DECREF(item_result);
                    PyErr_SetString(PyExc_TypeError,
                        "result array type does not match underlying function");
                    goto err;
                }
                Py_DECREF(item_result);
            }
            PyArray_ITER_NEXT(in_iter);
            PyArray_ITER_NEXT(out_iter);
        }
    }

    Py_DECREF(in_iter);
    Py_DECREF(out_iter);
    return (PyObject*)result;

err:
    Py_XDECREF(in_iter);
    Py_XDECREF(out_iter);
    Py_XDECREF(result);
    return 0;
}

/* Resolve method name to fast check function pointers */
static int
_get_fast_checks(PyObject *method_name, int is_unicode,
                 _fast_unicode_check *ucheck, _fast_bytes_check *bcheck)
{
    const char *name = PyUnicode_AsUTF8(method_name);
    if (name == NULL) return 0;

    if (strcmp(name, "isalpha") == 0) {
        *ucheck = _unicode_isalpha_ascii;
        *bcheck = _bytes_isalpha_ascii;
    }
    else if (strcmp(name, "isdigit") == 0) {
        *ucheck = _unicode_isdigit_ascii;
        *bcheck = _bytes_isdigit_ascii;
    }
    else if (strcmp(name, "isalnum") == 0) {
        *ucheck = _unicode_isalnum_ascii;
        *bcheck = _bytes_isalnum_ascii;
    }
    else if (strcmp(name, "isspace") == 0) {
        *ucheck = _unicode_isspace_ascii;
        *bcheck = _bytes_isspace_ascii;
    }
    else if (strcmp(name, "islower") == 0) {
        *ucheck = _unicode_islower_ascii;
        *bcheck = _bytes_islower_ascii;
    }
    else if (strcmp(name, "isupper") == 0) {
        *ucheck = _unicode_isupper_ascii;
        *bcheck = _bytes_isupper_ascii;
    }
    else if (strcmp(name, "istitle") == 0) {
        *ucheck = _unicode_istitle_ascii;
        *bcheck = _bytes_istitle_ascii;
    }
    else if (strcmp(name, "isnumeric") == 0) {
        *ucheck = _unicode_isnumeric_ascii;
        *bcheck = _bytes_isnumeric_ascii;
    }
    else if (strcmp(name, "isdecimal") == 0) {
        *ucheck = _unicode_isdecimal_ascii;
        *bcheck = _bytes_isdecimal_ascii;
    }
    else {
        return 0;
    }
    return 1;
}

