        c = buf[i];
        if (c == 0) break;
        if (c >= 128) return -1;
        if (c >= 'A' && c <= 'Z') {
            if (!expect_upper) return 0;
            has_cased = 1;
            expect_upper = 0;
        }
        else if (c >= 'a' && c <= 'z') {
            if (expect_upper) return 0;
            has_cased = 1;
        }
        else {
            expect_upper = 1;
        }
    }
    return has_cased ? 1 : 0;
}

