_unicode_isnumeric_ascii(const npy_ucs4 *buf, npy_intp num_chars)
{
    npy_ucs4 c = buf[0];
    if (c == 0) return 0;
    for (npy_intp i = 0; i < num_chars; i++) {
        c = buf[i];
        if (c == 0) return 1;
        if (c >= 128) return -1;
        if (!(c >= '0' && c <= '9')) return 0;
    }
    return 1;
}

